sys_script_include.script:
var ScheduleUtils = Class.create();
ScheduleUtils.prototype = {
    initialize: function() {},

    refQualSchedule: function() {
        var blockedNumbers = [];
        var schedulesToBeShown = [];

        var grEnrollment = new GlideRecord("x_1793782_traini_0_enrollment");
        grEnrollment.addQuery("opened_by", gs.getUserID());
        grEnrollment.addQuery("state", "!=", "4");
        grEnrollment.query();

        while (grEnrollment.next()) {
            var sch = grEnrollment.schedule.getRefRecord();
            if (sch && sch.number) {
                blockedNumbers.push(sch.number.toString());
            }
        }

        var grSchedules = new GlideRecord("x_1793782_traini_0_schedule");
        grSchedules.addQuery("state", "2");
        grSchedules.query();

        while (grSchedules.next()) {
            if (blockedNumbers.indexOf(grSchedules.number.toString()) == -1) {
                schedulesToBeShown.push(grSchedules.getUniqueValue());
            }
        }

        return schedulesToBeShown.length > 0
            ? "sys_idIN " + schedulesToBeShown.join(",")
            : "sys_idIN none";
    },

    type: 'ScheduleUtils'
};
